useForm<{
    cdsid: string;
    requestReference: string;
  }>({
    mode: 'onChange',
    defaultValues: { cdsid: '', requestReference: '' },
  })

handleSubmit(({ cdsid, requestReference }) => {
        reset();
        setLastUser(cdsid);
        onSave(cdsid, requestReference);
      })

register('cdsid', {
                required: true,
                disabled: loading,
                onChange: () => lastUser && setLastUser(''),
                pattern: {
                  value: /@volvocars.com$/,
                  message: 'CDSID must end with @volvocars.com',
                },
                minLength: {
                  value: 15,
                  message: 'CDSID must be at least 15 characters long',
                },
                validate: (value) => {
                  const user = superAdmins?.find(
                    (u) => u.cdsid.toLowerCase() === value.toLowerCase(),
                  );

                  if (user) {
                    return `User ${user.cdsid} has already super admin rights.`;
                  }
                },
              })
